\label{prop:reorganization-operators}
Given a family $\{C_{i j}\}_{i \in \mathcal{I}, j \in \mathcal{J}}$ of 
channels indexed by sets $\mathcal{I}$ and $\mathcal{J}$,
a distribution $\mu$ on $\mathcal{I}$, and
a distribution $\eta$ on $\mathcal{J}$:

\begin{enumerate}
\renewcommand{\alph{enumi})}{(\alph{enumi})}
\setlength{\itemsep}{\wideitemsep}\setlength{\itemsep}{\wideitemsep}\setlength{\itemsep}{\wideitemsep}\setlength{\itemsep}{\wideitemsep}\item 
${{\osum_{i \leftarrow \mu}} \;{\osum_{j \leftarrow \eta}} C_{i j} = {\osum_{\substack{i \leftarrow \mu\\ j \leftarrow \eta}}} C_{i j}}$, if all $C_{i}$'s have the same type;\\      

\setlength{\itemsep}{\wideitemsep}\setlength{\itemsep}{\wideitemsep}\setlength{\itemsep}{\wideitemsep}\setlength{\itemsep}{\wideitemsep}\item 
${{\bigsqcupdot_{i \leftarrow \mu}} \; {\bigsqcupdot_{j \leftarrow \eta}} C_{i j} \approx {\bigsqcupdot_{\substack{i \leftarrow \mu\\ j \leftarrow \eta}}} C_{i j}}$, if all $C_{i}$'s are compatible; and\\      

\setlength{\itemsep}{\wideitemsep}\setlength{\itemsep}{\wideitemsep}\setlength{\itemsep}{\wideitemsep}\setlength{\itemsep}{\wideitemsep}\item \label{item:c}
${{\osum_{i \leftarrow \mu}} \; {\bigsqcupdot_{j \leftarrow \eta}} C_{i j} \approx {\bigsqcupdot_{j \leftarrow \eta}}\; {\osum_{i \leftarrow \mu}} C_{i j}}$, 
if, for each $i$, all $C_{i j}$'s have same type $\mathcal{X} \times \mathcal{Y}_{j}\rightarrow\mathbb{R}$.
\end{enumerate}

\label{theo:order:II-I}



\begin{align*}
\min_\delta\max_{\sigma_{\sf a}} \mathbb{V}\left[\pi,{\bigsqcupdot_{\substack{d \leftarrow \delta\\ \textit{s}_{\sf a} \leftarrow {\sigma_{\sf a}}}}}  C_{d \textit{s}_{\sf a}(d)}\right] 
&\geq
\min_\delta\max_\alpha \mathbb{V}\left[\pi,{\bigsqcupdot_{\substack{d \leftarrow \delta\\ a \leftarrow \alpha}}} C_{da}\right]
\end{align*}

\label{theo:order:I-III}



\begin{align*}
\min_\delta\max_\alpha \mathbb{V}\left[\pi,{\bigsqcupdot_{\substack{d \leftarrow \delta\\ a \leftarrow \alpha}}} C_{da}\right]
\,\,\geq\,\,
\max_\alpha  \min_{{\sigma_{\sf d}}}{\mathbb{V}\left[\pi,{\bigsqcupdot_{\substack{\textit{s}_{\sf d} \leftarrow {\sigma_{\sf d}}\\ a \leftarrow \alpha}}}  C_{\textit{s}_{\sf d}(a) a}\right] }
\end{align*}

\label{theo:order:IV-VI}
\begin{align*}
\min_\delta\max_\alpha\mathbb{V}\left[\pi,{\bigsqcupdot_{a \leftarrow \alpha}}\, {{\osum_{d \leftarrow \delta}}} {C_{d a}}\right] &\geq
\max_\alpha  \min_{{\sigma_{\sf d}}} {\mathbb{V}\left[\pi, {\bigsqcupdot_{a \leftarrow \alpha}}\;{\osum_{\textit{s}_{\sf d} \leftarrow {\sigma_{\sf d}}}}  C_{\textit{s}_{\sf d}(a) a} \right] }
\end{align*}

\label{theo:order:I-IV}
\begin{align*}
\min_\delta\max_\alpha \mathbb{V}\left[\pi,{\bigsqcupdot_{\substack{d \leftarrow \delta\\ a \leftarrow \alpha}}} C_{da}\right]
\;\; \geq\;\;
\min_\delta\max_\alpha\mathbb{V}\left[\pi,{\bigsqcupdot_{a \leftarrow \alpha}}\, {{\osum_{d \leftarrow \delta}}} {C_{d a}}\right]
\end{align*}

\label{theo:order:III-VI}
\begin{align*}
\max_\alpha  \min_{{\sigma_{\sf d}}}{\mathbb{V}\left[\pi,{\bigsqcupdot_{\substack{\textit{s}_{\sf d} \leftarrow {\sigma_{\sf d}}\\ a \leftarrow \alpha}}}  C_{\textit{s}_{\sf d}(a) a}\right] }
\;\; \geq\;\;
\max_\alpha  \min_{{\sigma_{\sf d}}} {\mathbb{V}\left[\pi,{\bigsqcupdot_{a \leftarrow \alpha}}\;{\osum_{\textit{s}_{\sf d} \leftarrow {\sigma_{\sf d}}}}  C_{\textit{s}_{\sf d}(a) a}\right] }
\end{align*}

\label{cor:mixed-behavioral}
\[
\max_\alpha  \min_{{\sigma_{\sf d}}} {\mathbb{V}\left[\pi,{\bigsqcupdot_{a \leftarrow \alpha}}\;{\osum_{\textit{s}_{\sf d} \leftarrow {\sigma_{\sf d}}}}  C_{\textit{s}_{\sf d}(a) a}\right] }
\,\geq \,
\max_\alpha  \min_{{\phi_{\sf d}}} {\mathbb{V}\left[\pi,{\bigsqcupdot_{a \leftarrow \alpha}}\;{\osum_{d \leftarrow {\phi_{\sf d}}(a)}}  C_{d a}\right] }
\]

\label{prop:distributivity}
Let $C_{1}$, $C_{2}$ and $C_{3}$ be compatible channels,
and $C_{2}$ and $C_{3}$ have the same type.
Then, for any values $0 \leq p,q \leq 1$:
\begin{align*}
C_{1} \;{{}_{p}{\mathlarger{\mathlarger{\sqcupdot}}}}\; (C_{2} \;{{}_{q}{\mathlarger{\mathlarger{\oplus}}}}\; C_{3}) \approx (C_{1} \;{{}_{p}{\mathlarger{\mathlarger{\sqcupdot}}}}\; C_{2}) \;{{}_{q}{\mathlarger{\mathlarger{\oplus}}}}\; (C_{1} \;{{}_{p}{\mathlarger{\mathlarger{\sqcupdot}}}}\; C_{3}).
\end{align*}
